public class Solution {
    public static void main(String[] args) {
        int n = 3;
        int[][] matrix = new int[n][n];
        int val = 1;
        int top = 0, bottom = n - 1, left = 0, right = n - 1;

        while (val <= n * n) {
            for (int j = left; j <= right && val <= n * n; j++) matrix[top][j] = val++;
            top++;
            for (int i = top; i <= bottom && val <= n * n; i++) matrix[i][right] = val++;
            right--;
            for (int j = right; j >= left && val <= n * n; j--) matrix[bottom][j] = val++;
            bottom--;
            for (int i = bottom; i >= top && val <= n * n; i--) matrix[i][left] = val++;
            left++;
        }

        System.out.println("Spiral Matrix (3x3):");
        for (int[] row : matrix) {
            for (int cell : row) System.out.printf("%2d ", cell);
            System.out.println();
        }
    }
}

public class Solution {
    public static boolean isValidSudoku(char[][] board) {
        int[] rows = new int[9];
        int[] cols = new int[9];
        int[] boxes = new int[9];

        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                char ch = board[r][c];
                if (ch == '.') continue;
                int val = ch - '0';
                int bit = 1 << val;
                int boxIdx = (r / 3) * 3 + (c / 3);

                if ((rows[r] & bit) != 0 || (cols[c] & bit) != 0 || (boxes[boxIdx] & bit) != 0) {
                    return false;
                }
                rows[r] |= bit;
                cols[c] |= bit;
                boxes[boxIdx] |= bit;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        char[][] board = {
            {'5','3','.','.','7','.','.','.','.'},
            {'6','.','.','1','9','5','.','.','.'},
            {'.','9','8','.','.','.','.','6','.'},
            {'8','.','.','.','6','.','.','.','3'},
            {'4','.','.','8','.','3','.','.','1'},
            {'7','.','.','.','2','.','.','.','6'},
            {'.','6','.','.','.','.','2','8','.'},
            {'.','.','.','4','1','9','.','.','5'},
            {'.','.','.','.','8','.','.','7','9'}
        };
        System.out.println("Is valid Sudoku configuration: " + isValidSudoku(board));
    }
}

public class Solution {
    public static boolean hasCycle(int[] jumps) {
        if (jumps == null || jumps.length == 0) return false;
        int slow = 0, fast = 0;
        while (fast < jumps.length && jumps[fast] < jumps.length && jumps[jumps[fast]] < jumps.length) {
            slow = jumps[slow];
            fast = jumps[jumps[fast]];
            if (slow == fast) {
                return true; // Cycle detected
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int[] jumpPath = {1, 2, 3, 4, 1}; // Jumps: 0->1->2->3->4->1 (cycle)
        System.out.println("Cycle detected in jump path: " + hasCycle(jumpPath));
    }
}

public class Solution {
    public static void printKMax(int[] arr, int k) {
        System.out.print("Sliding window maximums (k=" + k + "): ");
        for (int i = 0; i <= arr.length - k; i++) {
            int max = arr[i];
            for (int j = 1; j < k; j++) {
                if (arr[i + j] > max) {
                    max = arr[i + j];
                }
            }
            System.out.print(max + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        int[] data = {1, 3, -1, -3, 5, 3, 6, 7};
        printKMax(data, 3);
    }
}

public class Solution {
    public static void main(String[] args) {
        int width = 30, height = 12;
        int maxIter = 50;

        for (int y = 0; y < height; y++) {
            double ci = -1.0 + (y * 2.0 / (height - 1));
            for (int x = 0; x < width; x++) {
                double cr = -2.0 + (x * 2.5 / (width - 1));
                double zr = 0.0, zi = 0.0;
                int iter = 0;
                while ((zr * zr + zi * zi) <= 4.0 && iter < maxIter) {
                    double nextZr = (zr * zr) - (zi * zi) + cr;
                    double nextZi = (2.0 * zr * zi) + ci;
                    zr = nextZr;
                    zi = nextZi;
                    iter++;
                }
                System.out.print(iter == maxIter ? "*" : " ");
            }
            System.out.println();
        }
    }
}
